package protocol

import (
	"fmt"
	"testing"
)

func TestScratch0704(t *testing.T) {
	multi := ""
	h2, m2, err := ParsePaketMessageIdAuto(multi)
	if err != nil { t.Fatal(err) }
	locs2, err := GetLocationBatchAuto(h2, m2)
	fmt.Printf("多条帧: %d条 err=%v phone=%s\n", len(locs2), err, h2.TerminalPhone)
	for i, l := range locs2 {
		fmt.Printf("  [%d] lat=%.6f lon=%.6f speed=%s time=%s\n", i, l.Lat, l.Lon, l.Speed, l.CreateTime)
	}
}
